import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
import {normalizeErrorStackOptions} from './dist/error-options.js';
import {processStackString,processStackFrames} from './dist/error-stack.js';
assert.equal(normalizeErrorStackOptions(null),undefined);
const stack='Error: test\r\n    at /app/src/index.ts:1:1\r\n    at /app/file.js:2:3';
const opts=normalizeErrorStackOptions({mode:'string',normalizeNewlines:true,stripInternalFrames:'superjson',maxStackLines:2});
assert.equal(processStackString(stack,opts),'Error: test');
assert.equal(processStackFrames(stack,opts)[1].raw,'at /app/file.js:2:3');
for (const container of [e=>e,e=>[e],e=>({e}),e=>new Map([['e',e]]),e=>new Set([e])]) {
 const s=new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',maxCauseDepth:1,sanitizeMessage:true}}); s.allowErrorProps('stackFrames');
 const cause=new Error('a@b.com'); cause.cause=new Error('deeper'); const e=new Error('1.2.3.4',{cause}); e.stack='Error: header\n    at /app/file.js:1:1';
 const p=s.serialize(container(e)); const text=s.stringify(container(e)); const result=s.parse(text); assert.ok(result); assert.ok(text.includes('[redacted]')); assert.ok(!text.includes('deeper')); assert.ok(text.includes('stackFrames'));
}
const a=new SuperJSON({errorStack:{mode:'off'}}); a.allowErrorProps('stack'); assert.ok(!('stack' in a.serialize(new Error('test')).json));
const x=new SuperJSON({errorStack:{mode:'string'}}); x.allowErrorProps('stack'); x.registerErrorStackProcessor('Error', obj=>({...obj, custom:true})); assert.equal(x.serialize(new Error('test')).json.custom,true);
const cyc=new Error('c'); cyc.cause=cyc; assert.doesNotThrow(()=>new SuperJSON({errorStack:{includeCauses:'deep'}}).stringify(cyc));
console.log('Focused checks passed');
